//! Named TLS security policies (AWS load balancers, CloudFront, API
//! Gateway, Mozilla) and what each allows.
//!
//! The catalogue `kb/tls_policies.yaml` is generated by
//! `scripts/fetch_aws_tls_policies.py` from the published pages and embedded
//! in the binary. Loading validates it: every protocol is known, every
//! cipher resolves in the IANA table (any notation is accepted and stored by
//! its IANA name), TLS 1.3 suites and TLS 1.2 ciphers sit in the right list,
//! and ids are unique per provider (ALB and NLB publish policies of the same
//! names).

use std::collections::HashSet;
use std::sync::OnceLock;

use anyhow::{Result, bail};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

use crate::ciphers::{Cipher, Protocol};

pub mod conformance;

/// The catalogue as shipped.
pub const BUILTIN_POLICIES: &str = include_str!("../../kb/tls_policies.yaml");

/// Who publishes a policy.
#[derive(
    Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize, JsonSchema, clap::ValueEnum,
)]
#[serde(rename_all = "snake_case")]
pub enum PolicyProvider {
    /// Application Load Balancer `ELBSecurityPolicy-*`.
    #[value(name = "aws_alb", alias = "aws-alb")]
    AwsAlb,
    /// Network Load Balancer `ELBSecurityPolicy-*`.
    #[value(name = "aws_nlb", alias = "aws-nlb")]
    AwsNlb,
    /// CloudFront viewer security policies.
    #[value(name = "aws_cloudfront", alias = "aws-cloudfront")]
    AwsCloudfront,
    /// API Gateway security policies.
    #[value(name = "aws_api_gateway", alias = "aws-api-gateway")]
    AwsApiGateway,
    /// Mozilla server side TLS configurations.
    #[value(name = "mozilla")]
    Mozilla,
}

impl PolicyProvider {
    /// The name the catalogue and the CLI use, e.g. `aws_alb`.
    pub fn label(self) -> &'static str {
        match self {
            Self::AwsAlb => "aws_alb",
            Self::AwsNlb => "aws_nlb",
            Self::AwsCloudfront => "aws_cloudfront",
            Self::AwsApiGateway => "aws_api_gateway",
            Self::Mozilla => "mozilla",
        }
    }
}

/// One named policy.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct TlsPolicy {
    /// The provider's name for the policy, e.g. `ELBSecurityPolicy-TLS13-1-2-Res-PQ-2025-09`.
    pub id: String,
    pub provider: PolicyProvider,
    /// Protocol versions the policy accepts: `1.0`, `1.1`, `1.2`, `1.3`.
    pub protocols: Vec<String>,
    /// TLS 1.3 suites, by IANA name.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub tls13_suites: Vec<String>,
    /// TLS 1.2 and earlier ciphers, by IANA name, in the provider's order.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub tls12_ciphers: Vec<String>,
    /// Key exchange groups the provider names for the policy.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub groups: Vec<String>,
    /// The provider does not list the classical groups it accepts.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub unspecified_classical: bool,
    /// Approved for FIPS 140 workloads by the provider.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub fips: bool,
    /// Offers ML-KEM hybrid key exchange.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub post_quantum: bool,
    /// Where the provider applies this policy by default, in the provider's
    /// words: `console`, `cli`, or an API Gateway resource such as `Regional APIs`.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub default_for: Vec<String>,
    /// The page the policy was taken from.
    pub source_url: String,
    /// When that page was read, `YYYY-MM-DD`.
    pub retrieved: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub notes: Option<String>,
}

/// The catalogue file.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct PolicyCatalogue {
    /// Format version, currently 1.
    pub version: u32,
    pub policies: Vec<TlsPolicy>,
}

const PROTOCOLS: &[&str] = &["1.0", "1.1", "1.2", "1.3"];

impl TlsPolicy {
    /// Check the policy and store every cipher by its IANA name.
    fn normalise(&mut self) -> Result<()> {
        let id = self.id.clone();
        if self.protocols.is_empty() {
            bail!("{id}: no protocols");
        }
        if let Some(bad) = self.protocols.iter().find(|p| !PROTOCOLS.contains(&p.as_str())) {
            bail!(
                "{id}: unknown protocol `{bad}` (expected one of {})",
                PROTOCOLS.join(", ")
            );
        }
        let resolve = |names: &[String], family: Protocol, list: &str| -> Result<Vec<String>> {
            names
                .iter()
                .map(|name| {
                    let cipher = Cipher::parse(name).map_err(|e| anyhow::anyhow!("{id}: {list}: {e}"))?;
                    if cipher.protocol != family {
                        bail!("{id}: {list} lists {}, which belongs to the other family", cipher.iana);
                    }
                    Ok(cipher.iana.to_string())
                })
                .collect()
        };
        self.tls13_suites = resolve(&self.tls13_suites, Protocol::Tls13, "tls13_suites")?;
        self.tls12_ciphers = resolve(&self.tls12_ciphers, Protocol::Tls12, "tls12_ciphers")?;
        let has_13 = self.protocols.iter().any(|p| p == "1.3");
        if has_13 != !self.tls13_suites.is_empty() {
            bail!("{id}: TLS 1.3 suites must be listed exactly when TLS 1.3 is a protocol");
        }
        if self.protocols.iter().any(|p| p != "1.3") && self.tls12_ciphers.is_empty() {
            bail!("{id}: TLS 1.2 or earlier is a protocol but no TLS 1.2 ciphers are listed");
        }
        if self.source_url.is_empty() || self.retrieved.len() != 10 {
            bail!("{id}: source_url and a YYYY-MM-DD retrieved date are required");
        }
        Ok(())
    }

    /// Whether the policy accepts `version` (`1.2`).
    pub fn allows(&self, version: &str) -> bool {
        self.protocols.iter().any(|p| p == version)
    }
}

impl PolicyCatalogue {
    /// Parse and validate a catalogue.
    pub fn parse(yaml: &str) -> Result<Self> {
        let mut catalogue: PolicyCatalogue = serde_norway::from_str(yaml)?;
        if catalogue.version != 1 {
            bail!("unsupported catalogue version {}", catalogue.version);
        }
        let mut seen = HashSet::new();
        for policy in &mut catalogue.policies {
            if !seen.insert((policy.provider, policy.id.clone())) {
                bail!("duplicate policy {} for {:?}", policy.id, policy.provider);
            }
            policy.normalise()?;
        }
        Ok(catalogue)
    }

    /// The embedded catalogue.
    pub fn builtin() -> Result<&'static PolicyCatalogue> {
        static CATALOGUE: OnceLock<Result<PolicyCatalogue, String>> = OnceLock::new();
        CATALOGUE
            .get_or_init(|| PolicyCatalogue::parse(BUILTIN_POLICIES).map_err(|e| e.to_string()))
            .as_ref()
            .map_err(|e| anyhow::anyhow!("built in TLS policy catalogue: {e}"))
    }

    /// Every policy with this id, ignoring case, optionally of one provider.
    pub fn find(&self, id: &str, provider: Option<PolicyProvider>) -> Vec<&TlsPolicy> {
        self.by_provider(provider)
            .filter(|p| p.id.eq_ignore_ascii_case(id))
            .collect()
    }

    /// The one policy with this id of `provider`.
    pub fn get(&self, id: &str, provider: PolicyProvider) -> Option<&TlsPolicy> {
        self.find(id, Some(provider)).into_iter().next()
    }

    /// Policies of one provider, or all.
    pub fn by_provider(&self, provider: Option<PolicyProvider>) -> impl Iterator<Item = &TlsPolicy> {
        self.policies
            .iter()
            .filter(move |p| provider.is_none_or(|v| p.provider == v))
    }

    /// JSON schema for the YAML file, for editor validation.
    pub fn json_schema() -> serde_json::Value {
        serde_json::to_value(schemars::schema_for!(PolicyCatalogue)).unwrap_or_default()
    }
}

#[cfg(test)]
mod tests {
    #![allow(clippy::expect_used, clippy::unwrap_used, clippy::panic)]

    use super::*;

    fn builtin() -> &'static PolicyCatalogue {
        PolicyCatalogue::builtin().expect("the built in catalogue loads")
    }

    const ALB_TLS12: &[&str] = &[
        "TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256",
        "TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256",
        "TLS_ECDHE_ECDSA_WITH_AES_256_GCM_SHA384",
        "TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384",
    ];
    const ALB_TLS13: &[&str] = &[
        "TLS_AES_128_GCM_SHA256",
        "TLS_AES_256_GCM_SHA384",
        "TLS_CHACHA20_POLY1305_SHA256",
    ];
    const HYBRIDS: &[&str] = &["X25519MLKEM768", "SecP256r1MLKEM768", "SecP384r1MLKEM1024"];

    fn sorted(list: &[String]) -> Vec<&str> {
        let mut v: Vec<&str> = list.iter().map(String::as_str).collect();
        v.sort_unstable();
        v
    }

    fn sorted_str(list: &[&'static str]) -> Vec<&'static str> {
        let mut v = list.to_vec();
        v.sort_unstable();
        v
    }

    #[test]
    fn the_tls13_only_pq_policy_matches_the_aws_page() {
        let p = builtin()
            .get("ELBSecurityPolicy-TLS13-1-3-PQ-2025-09", PolicyProvider::AwsAlb)
            .expect("present");
        assert_eq!(p.provider, PolicyProvider::AwsAlb);
        assert_eq!(p.protocols, ["1.3"]);
        assert!(p.tls12_ciphers.is_empty());
        assert_eq!(sorted(&p.tls13_suites), sorted_str(ALB_TLS13));
        assert_eq!(sorted(&p.groups), sorted_str(HYBRIDS));
        assert!(p.post_quantum && p.unspecified_classical);
    }

    #[test]
    fn the_restricted_pq_policy_matches_the_aws_page() {
        let p = builtin()
            .get("ELBSecurityPolicy-TLS13-1-2-Res-PQ-2025-09", PolicyProvider::AwsAlb)
            .expect("present");
        assert_eq!(sorted(&p.protocols), ["1.2", "1.3"]);
        assert_eq!(sorted(&p.tls12_ciphers), sorted_str(ALB_TLS12));
        assert_eq!(sorted(&p.tls13_suites), sorted_str(ALB_TLS13));
        assert_eq!(sorted(&p.groups), sorted_str(HYBRIDS));
        assert_eq!(p.default_for, ["console"]);
    }

    #[test]
    fn thirteen_alb_pq_policies_and_fips_twins_without_chacha() {
        let alb_pq: Vec<&TlsPolicy> = builtin()
            .by_provider(Some(PolicyProvider::AwsAlb))
            .filter(|p| p.post_quantum)
            .collect();
        assert_eq!(
            alb_pq.len(),
            13,
            "{:?}",
            alb_pq.iter().map(|p| &p.id).collect::<Vec<_>>()
        );
        assert_eq!(alb_pq.iter().filter(|p| p.fips).count(), 7);
        for p in alb_pq.iter().filter(|p| p.fips) {
            assert!(
                !p.tls13_suites.iter().any(|s| s.contains("CHACHA20")),
                "{} is FIPS but lists ChaCha20",
                p.id
            );
        }
        assert_eq!(
            builtin()
                .get("ELBSecurityPolicy-2016-08", PolicyProvider::AwsAlb)
                .map(|p| p.default_for.clone()),
            Some(vec!["cli".to_string()])
        );
        assert_eq!(
            builtin().find("ELBSecurityPolicy-2016-08", None).len(),
            2,
            "ALB and NLB"
        );
    }

    #[test]
    fn every_entry_has_a_source_and_a_retrieval_date() {
        for p in &builtin().policies {
            assert!(p.source_url.starts_with("https://"), "{}", p.id);
            assert_eq!(p.retrieved.len(), 10, "{}", p.id);
        }
        for provider in [
            PolicyProvider::AwsAlb,
            PolicyProvider::AwsNlb,
            PolicyProvider::AwsCloudfront,
            PolicyProvider::AwsApiGateway,
            PolicyProvider::Mozilla,
        ] {
            assert!(builtin().by_provider(Some(provider)).count() > 0, "{provider:?}");
        }
    }

    #[test]
    fn the_loader_normalises_any_notation_and_rejects_mistakes() {
        let yaml = |ciphers: &str, protocols: &str| {
            format!(
                "version: 1\npolicies:\n  - id: t\n    provider: mozilla\n    protocols: [{protocols}]\n    tls12_ciphers: [{ciphers}]\n    source_url: https://example.test\n    retrieved: 2026-10-26\n"
            )
        };
        let ok = PolicyCatalogue::parse(&yaml("ECDHE-RSA-AES128-GCM-SHA256, '0xC030'", "'1.2'")).unwrap();
        assert_eq!(
            ok.policies[0].tls12_ciphers,
            [
                "TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256",
                "TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384"
            ]
        );
        assert!(PolicyCatalogue::parse(&yaml("NOT-A-CIPHER", "'1.2'")).is_err());
        assert!(PolicyCatalogue::parse(&yaml("TLS_AES_128_GCM_SHA256", "'1.2'")).is_err());
        assert!(PolicyCatalogue::parse(&yaml("C02F", "'2.0'")).is_err());
        assert!(PolicyCatalogue::parse(&yaml("C02F", "'1.3'")).is_err());
    }

    #[test]
    fn schema_file_is_current() {
        let expected = serde_json::to_string_pretty(&PolicyCatalogue::json_schema()).unwrap();
        let on_disk = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/kb/tls_policies.schema.json"))
            .unwrap_or_default();
        assert_eq!(
            on_disk.trim(),
            expected.trim(),
            "kb/tls_policies.schema.json is stale; run `dcert policy schema > kb/tls_policies.schema.json`"
        );
    }
}
